import html
import json
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "research"))
import generar_documento as D

DATA = json.loads((ROOT / "research" / "dataset.json").read_text(encoding="utf-8"))
COV = json.loads((ROOT / "research" / "cobertura_territorial.json").read_text(encoding="utf-8"))
ITEMS, BASE, SECOP = DATA["items"], D.BASE, D.SECOP
STATUS = D.STATUS
e = D.e
SITE = D.SITE
PDF = D.PDF
COVER_STATUS = {"hecha": "Hallazgo", "sin_hallazgo": "Sin hallazgo", "limitada": "Limitada", "pendiente": "Pendiente"}
LAYER = {item["id"]: item for item in COV["required_layers"]}


def secop_rows():
    rows = []
    for item in SECOP:
        signal = "Directa" if item.get("match_directo") else "Intersección"
        rows.append(f"<tr><td><a href='{e(item['fuentes'][0]['url'])}'>{e(item['referencia'])}</a><br><span class='tiny'>{e(item['id_proceso'])}</span></td><td>{e(item['entidad'])}<br><span class='tiny'>{e(item['territorio'])}</span></td><td>{e(item['nombre'])}</td><td>{e(signal)}</td><td class='num'>{e(item['monto'].replace(' COP',''))}</td><td>{e(item['actualizacion'][:10])}</td></tr>")
    return "".join(rows)


def ficha(item):
    return D.ficha(item)


def coverage_cell(record, layer):
    evidence = next((x for x in record["evidence"] if x["layer"] == layer), None)
    if not evidence:
        return "<span class='badge pendiente'>Pendiente</span>"
    return f"<a href='{e(evidence['url'])}' class='small'>{e(COVER_STATUS[evidence['status']])}</a>"


def coverage_rows():
    rows = []
    for record in COV["records"]:
        cells = "".join(f"<td>{coverage_cell(record, layer)}</td>" for layer in LAYER)
        gaps = ", ".join(LAYER[x]["name"] for x in record["gaps"]) or "—"
        rows.append(f"<tr><td><strong>{e(record['department'])}</strong></td>{cells}<td>{e(gaps)}</td></tr>")
    return "".join(rows)


def coverage_sources():
    seen, rows = set(), []
    for record in COV["records"]:
        for item in record["evidence"]:
            if item["url"] and item["url"] not in seen:
                seen.add(item["url"])
                rows.append(f"<li><strong>{e(record['department'])} · {e(LAYER[item['layer']]['name'])}</strong> — {e(item['source'])}<br><a href='{e(item['url'])}'>{e(item['url'])}</a></li>")
    return "".join(rows), len(seen)


def make_document():
    counts = Counter(x["estado"] for x in ITEMS)
    immediate = [x for x in BASE if x["estado"] == "abierta"]
    local_secop = [x for x in SECOP if x["cap"] == 1]
    national_base = [x for x in BASE if x["cap"] == 2]
    international = [x for x in BASE if x["cap"] == 3]
    complete = sum(not record["gaps"] for record in COV["records"])
    evidence_total = sum(len(record["evidence"]) for record in COV["records"])
    chapters = []
    chapters.append(f"""<section class='cover'><div><div class='kicker'>Investigación aplicada · Edición exhaustiva</div><h1>Economía plateada: universo de fuentes y financiación</h1><p class='lead'>32 departamentos + Bogotá D.C. · SECOP II depurado · regalías · ministerios · ONG · fondos internacionales</p></div><div><div class='grid-3'><div class='metric'><strong>{len(ITEMS)}</strong>registros trazables</div><div class='metric'><strong>33</strong>territorios auditados</div><div class='metric'><strong>{len(SECOP)}</strong>candidatos SECOP</div></div></div><div class='meta'><strong>Corte:</strong> {DATA['corte']}<br><strong>Corte SECOP:</strong> 18:45, hora de Colombia<br><strong>Versión:</strong> 2.0 · Cobertura y brechas explícitas<br><br><a href='{SITE}'>Explorador: {SITE}</a><br><a href='{SITE}cobertura.html'>Tablero de cobertura 33 × 6</a></div></section>""")
    chapters.append(f"""<section><div class='eyebrow'>Guía de lectura</div><h1>Qué cambia en esta edición</h1><p class='lead'>Se reemplazó la muestra de 27 procesos SECOP por un universo auditado de {len(SECOP)} candidatos y se añadió una matriz de cobertura para todos los territorios.</p><div class='grid-2'><div class='callout'><strong>Exhaustividad operativa</strong><br>32 departamentos + Bogotá; seis capas por territorio; SECOP consultado en nombre y descripción; evidencias y brechas visibles.</div><div class='callout warn'><strong>Límite verificable</strong><br>{complete} de 33 territorios tienen las seis capas resueltas. Las brechas de Cesar y Magdalena se muestran; no se declaran “sin oportunidad”.</div></div><div class='toc'><a href='#resumen'>Resumen ejecutivo</a><a href='#metodo'>Método de exhaustividad</a><a href='#cap1'>Capítulo 1 · Bogotá, Cundinamarca y CCB</a><a href='#cap2'>Capítulo 2 · Resto del país y regalías</a><a href='#secop'>Anexo SECOP II · {len(SECOP)} candidatos</a><a href='#cobertura'>Matriz 33 territorios × 6 capas</a><a href='#cap3'>Capítulo 3 · ONG y fondos internacionales</a><a href='#ruta'>Ruta de participación</a><a href='#fuentes'>Metodología, limitaciones y fuentes</a></div><h2>Regla de lectura</h2><p>Una fila SECOP es una <strong>candidatura temática sujeta a pliego</strong>, no una adjudicación, subvención o recepción vigente. Una capa territorial “sin hallazgo” significa que se revisó la navegación pública y no apareció un canal específico; “limitada” significa que el portal bloqueó o no entregó información útil.</p></section>""")
    chapters.append(f"""<section id='resumen'><div class='eyebrow'>Resumen ejecutivo</div><h1>El universo, no una muestra</h1><div class='grid-3'><div class='metric'><strong>{len(ITEMS)}</strong>registros</div><div class='metric'><strong>{DATA['secop_directos']}</strong>coincidencias SECOP directas</div><div class='metric'><strong>{DATA['secop_interseccion']}</strong>intersecciones por validar</div></div><h2>Hallazgos comprobables</h2><ol><li><strong>Se auditaron {len(COV['records'])} territorios.</strong> La matriz contiene {evidence_total} evidencias de capa; {complete} territorios tienen las seis capas resueltas y las brechas restantes están identificadas.</li><li><strong>SECOP II: {len(SECOP)} candidatos.</strong> Provienen de 12.850 procesos abiertos/publicados/no adjudicados de 2026 consultados en nombre y descripción. {DATA['secop_directos']} tienen coincidencia directa; {DATA['secop_interseccion']} son intersecciones que requieren validación humana.</li><li><strong>Bogotá–Cundinamarca mantiene las rutas locales más concretas:</strong> CCB, Estampilla y SECOP municipal. El programa CCB es gratuito y no promete capital; la Estampilla es una asignación institucional.</li><li><strong>No existe una convocatoria nacional general abierta de regalías para privados.</strong> SGR y OCAD Paz exigen entidad habilitada y aprobación; las convocatorias CTeI 54–56 revisadas están cerradas.</li><li><strong>Cooperación abierta:</strong> D-Prize, DRK y Pollination Project. CAF LIF 2026 cerró; IAF está pausada; Wellcome no admite sede colombiana; GIF prioriza África/Asia.</li><li><strong>La clasificación evita falsos positivos:</strong> subvención, contratación, asignación pública, transferencia individual, aceleración, kit, crowdfunding y asistencia técnica no se suman ni se presentan como equivalentes.</li></ol><div class='callout danger'><strong>Brecha de exhaustividad:</strong> Cesar y Magdalena requieren verificación manual adicional. El tablero las muestra con sus URLs y capas pendientes; el resto de territorios tiene una resolución documentada en las seis capas.</div></section>""")
    chapters.append("""<section id='metodo'><div class='eyebrow'>Método de exhaustividad</div><h1>Seis capas y una regla de cierre</h1><table><thead><tr><th>Capa</th><th>Qué se revisa</th><th>Qué demuestra</th></tr></thead><tbody><tr><td>1. SECOP II</td><td>Dataset p6dx-8zbt; nombre y descripción; 2026; abierto/publicado/no adjudicado; filtros de fase.</td><td>Candidatos de contratación, no subvención.</td><tr><td>2. Gobernación</td><td>Portal oficial y enlaces de planeación, proyectos, fondos y convocatorias.</td><td>Canal departamental consultado.</td><tr><td>3. Capital / distrito</td><td>Portal de la ciudad sede y oferta territorial.</td><td>Canal municipal consultado.</td><tr><td>4. Cultura</td><td>Secretarías, institutos, consejerías o patrimonio.</td><td>Canal cultural localizado o ausencia explícita.</td><tr><td>5. Participación / planeación</td><td>Participa, presupuesto participativo, planeación, acción comunal y CDPS.</td><td>Canal de participación o planeación.</td><tr><td>6. Bancos / regalías / fondos</td><td>Banco de proyectos, regalías, presupuesto, convocatorias y fondos.</td><td>Canal financiero o de inversión territorial.</td></tr></tbody></table><p><strong>Estados:</strong> Hallazgo = URL localizada; Sin hallazgo = navegación revisada sin canal visible; Limitada = portal bloqueado o sin menú útil; Pendiente = capa no ejecutada. Solo las dos últimas cuentan como brecha.</p><div class='callout'><strong>Principio:</strong> no se convierte una ausencia de enlace en una afirmación de que no existe financiación. Si no hay evidencia, se registra la brecha y la fuente debe revisarse de nuevo.</div></section>""")
    chapters.append(f"""<section class='chapter' id='cap1'>{D.chapter_intro(1,'Bogotá, Cundinamarca y CCB','Iniciativas locales, financiación, operación y presencia física')}<h2>Lectura regional</h2><p>Bogotá combina desarrollo empresarial, operación social, cuidado, cultura y participación. Cundinamarca aporta una asignación presupuestal específica, pero su acceso es municipal e institucional.</p><div class='grid-2'><div class='callout'><strong>Empresa/startup:</strong> CCB como entrada; SECOP para ingresos; CAF/DRK solo con tracción.</div><div class='callout'><strong>ESAL/organización:</strong> personería, experiencia, plan local; SDIS, PDAC, Chikaná y procesos municipales.</div></div><h2>Fichas locales y nacionales con incidencia en Bogotá–Cundinamarca</h2>{''.join(ficha(x) for x in BASE if x['cap']==1)}<h2>SECOP II en Bogotá y Cundinamarca</h2><p><strong>{len(local_secop)}</strong> candidatos de la selección; tabla completa con enlace y presupuesto. La ubicación es la reportada por la entidad y puede diferir del lugar de ejecución.</p><table><thead><tr><th>Proceso</th><th>Entidad / territorio</th><th>Objeto</th><th>Presupuesto</th><th>Actualización</th></tr></thead><tbody>{D.table_rows(local_secop,True)}</tbody></table></section>""")
    chapters.append(f"""<section class='chapter' id='cap2'>{D.chapter_intro(2,'Resto del país, regalías, ministerios y fondos','Programas nacionales, rutas territoriales y oportunidades verificables')}<h2>Arquitectura de financiación</h2><p>Cinco rutas: inversión pública SGR/OCAD; CTeI; capital semilla SENA; cultura/participación; y contratación territorial. Las transferencias como Colombia Mayor no son financiación institucional.</p><div class='callout warn'><strong>Ninguna convocatoria nacional general de MinCiencias, Fondo Emprender o MinCultura estaba abierta al corte.</strong> La Concertación Cultural se proyecta para enero–febrero de 2027.</div><h2>Fichas nacionales y de regalías</h2>{''.join(ficha(x) for x in national_base)}</section>""")
    secop_by_dept = Counter(x["departamento"] for x in SECOP)
    chapters.append(f"""<section class='chapter' id='secop'><div class='chapter-title'><div class='eyebrow'>Capítulo 2 · Anexo SECOP II</div><h1>{len(SECOP)} candidatos para revisión</h1><p class='lead'>Universo auditado de procesos de 2026, no una muestra de conveniencia.</p></div><h2>Embudo de depuración</h2><table><thead><tr><th>Etapa</th><th>Registros</th><th>Regla</th></tr></thead><tbody><tr><td>Consulta temática</td><td>12.850</td><td>Abierto/publicado/no adjudicado; publicación 2026; términos en nombre o descripción.</td><tr><td>Selección operativa</td><td>{len(SECOP)}</td><td>Fase de oferta/manifestación, no contratación directa, actualización desde 2026-10-01.</td><tr><td>Coincidencia directa</td><td>{DATA['secop_directos']}</td><td>Persona mayor, envejecimiento, vejez, geriatría, cuidadores, centro vida/día u otro término fuerte.</td><tr><td>Intersección por validar</td><td>{DATA['secop_interseccion']}</td><td>Cuidado, discapacidad o 60 años; requiere leer el objeto.</td></tbody></table><h2>Cobertura del anexo</h2><p>Los candidatos se distribuyen en <strong>{len(secop_by_dept)} departamentos/etiquetas territoriales</strong>, incluidos Putumayo, Casanare y las entidades con sede “No Definido”. No se suman presupuestos por la heterogeneidad de objetos y modalidades.</p><table><thead><tr><th>Departamento reportado</th><th>Candidatos</th></tr></thead><tbody>{''.join(f'<tr><td>{e(k)}</td><td class=num>{v}</td></tr>' for k,v in secop_by_dept.most_common())}</tbody></table><h2>Requisitos mínimos para ofertar</h2><div class='grid-2'><ul><li>Cuenta de proveedor SECOP II y RUP cuando aplique.</li><li>Leer aviso, estudios previos, pliego, anexos, adendas y respuestas.</li><li>Verificar experiencia, capacidad técnica/financiera, equipo, garantías y consorcios.</li><li>Confirmar objeto, cantidades, lugar, plazo, visitas y obligaciones sociales.</li></ul><ul><li>Preparar oferta técnica/económica y documentos en los formatos exigidos.</li><li>Presentar antes del cierre real.</li><li>Evaluar régimen especial/convenios y capacidad de ESAL.</li><li>Presupuestar supervisión, seguros, reportes, accesibilidad y protección de datos.</li></ul></div><div class='callout danger'><strong>Advertencia:</strong> el dataset no contiene fecha/hora de cierre. “Publicado” y “abierto” no garantizan recepción vigente; la ficha pública puede pedir captcha. Abra cada aviso antes de preparar una oferta.</div><h2>Tabla completa del universo SECOP</h2><p class='small'>“Directa” indica coincidencia con un término fuerte de personas mayores/cuidado; “Intersección” exige leer el objeto y no debe presentarse aún como oportunidad plateada validada.</p><table class='tiny'><thead><tr><th>Proceso / ID</th><th>Entidad / territorio</th><th>Objeto</th><th>Señal</th><th>Presupuesto</th><th>Actualización</th></tr></thead><tbody>{secop_rows()}</tbody></table></section>""")
    chapters.append(f"""<section class='chapter' id='cobertura'><div class='chapter-title'><div class='eyebrow'>Cobertura</div><h1>33 territorios × 6 capas</h1><p class='lead'>Matriz auditable: {complete} territorios con las seis capas resueltas y dos con brechas identificadas.</p></div><div class='grid-3'><div class='metric'><strong>33</strong>territorios</div><div class='metric'><strong>{evidence_total}</strong>evidencias de capa</div><div class='metric'><strong>{complete}</strong>con cobertura completa</div></div><p>Cada celda enlaza la evidencia registrada. <strong>Hallazgo</strong> indica un canal localizado; <strong>sin hallazgo</strong>, una navegación revisada sin enlace específico; <strong>limitada</strong>, un bloqueo técnico; <strong>pendiente</strong>, una capa no ejecutada.</p><table class='tiny'><thead><tr><th>Territorio</th>{''.join(f'<th>{e(LAYER[x]["name"])}</th>' for x in LAYER)}<th>Brechas</th></tr></thead><tbody>{coverage_rows()}</tbody></table><div class='callout danger'><strong>Cola de verificación:</strong> Cesar y Magdalena. Sus portales no entregaron navegación completa o bloquearon el acceso automático. No se afirma que no existan oportunidades; se indica que la evidencia está incompleta.</div><p><a href='{SITE}cobertura.html'>Abrir tablero interactivo de cobertura ↗</a></p></section>""")
    chapters.append(f"""<section class='chapter' id='cap3'>{D.chapter_intro(3,'ONG, cooperación y fondos internacionales','Ventanas abiertas, proyectos en implementación y restricciones para Colombia')}<h2>Prioridad por tipo de proyecto</h2><table><thead><tr><th>Proyecto</th><th>Fuente / condición crítica</th></tr></thead><tbody><tr><td>Distribución de gafas o solución probada contra pobreza</td><td>D-Prize hasta USD 20.000; nueva organización y piloto; prórroga 6 dic 2026.</td><tr><td>Empresa social plateada con tracción y escala</td><td>DRK hasta USD 300.000/3 años; no idea/pre-piloto.</td><tr><td>Acción comunitaria voluntaria temprana</td><td>Pollination Project; presupuestos pequeños, inglés y referee; 30 nov 2026.</td><tr><td>Recaudación internacional de ONG</td><td>GlobalGiving; invitación y due diligence, no grant garantizado.</td><tr><td>Startup financiera/digital 50+</td><td>CAF LIF, próxima edición; 2026 cerró.</td><tr><td>Ecosistema regional de startups</td><td>BID Silver Ventures en implementación; sin convocatoria abierta en ficha.</td><tr><td>Participación democrática de mayores</td><td>UNDEF, próxima ventana; no cuidado asistencial.</td><tr><td>Violencia contra mujeres mayores</td><td>ONU Mujeres, próxima estimada 2027.</td></tbody></table><div class='callout danger'><strong>No aplicar hoy:</strong> IAF (pausa), Wellcome Discovery (geografía) y Global Innovation Fund (África/Asia).</div>{''.join(ficha(x) for x in international)}</section>""")
    chapters.append(f"""<section class='chapter' id='ruta'><div class='chapter-title'><div class='eyebrow'>Implementación</div><h1>Ruta para convertir cobertura en decisiones</h1></div><h2>Regla de oro</h2><div class='callout'><strong>Primero el instrumento, después la postulación.</strong> Una empresa no “aplica” a la Estampilla; una ONG no “aplica” a un cupo contractual; un ciudadano no usa un fondo de proyectos como transferencia. Identifique su rol antes de preparar documentos.</div><h2>Secuencia</h2><ol><li><strong>Días 1–7:</strong> abrir los 351 candidatos directos de SECOP, descartar cierres vencidos y asignar dueño. Inscribirse en CCB. Verificar fuentes de D-Prize, DRK y Pollination.</li><li><strong>Días 8–30:</strong> preparar carpeta maestra: personería/RUT, experiencia, estados financieros, equipo, resultados, presupuesto, contrapartida, riesgos y accesibilidad.</li><li><strong>Días 31–60:</strong> elegir arquetipo (cuidado, inclusión financiera, cultura, participación, tecnología o distribución) y validar requisitos con la entidad.</li><li><strong>Días 61–90:</strong> presentar solo donde exista canal vigente; registrar aprendizajes y reprogramar vigilancia.</li><li><strong>Permanente:</strong> actualizar SECOP, cobertura territorial, MinCiencias, MinCultura, SGR, CCB y fondos internacionales.</li></ol><h2>Matriz por postulante</h2><table><thead><tr><th>Si usted es…</th><th>Puede buscar</th><th>No confundir con</th></tr></thead><tbody><tr><td>Empresa / startup</td><td>CCB, DRK, D-Prize, SECOP, futuras CAF/Fondo Emprender</td><td>Estampilla, SGR o transferencias</td><tr><td>ESAL / OSC</td><td>Chikaná, PDAC, SDIS, Pollination, GlobalGiving, UNDEF/ONU Mujeres cuando aplique</td><td>Contratos que exigen experiencia/operación</td><tr><td>Entidad pública</td><td>SGR, OCAD, Estampilla, convocatorias territoriales</td><td>Capital semilla privado</td><tr><td>Persona / grupo</td><td>Idartes, Pollination, programas municipales, Colombia Mayor</td><td>Fondos que exigen persona jurídica</td><tr><td>Academia / IES</td><td>MinCiencias, BID, DRK si es empresa social, SECOP de consultoría</td><td>Aceleración para startups sin tracción</td></tbody></table><h2>Control de presencia</h2><p>SECOP, CCB, CAF, DRK, D-Prize y GlobalGiving permiten aplicar en línea; la ejecución del piloto sí es territorial. Idartes Danza Mayor exige residencia en Bogotá y audición presencial. SGR/MinCiencias exigen intervención en el territorio y actor habilitado. SDIS exige operación física en Bogotá cuando se contrata el servicio.</p></section>""")
    unique = {}
    for item in BASE:
        for source in item["fuentes"]:
            unique[source["url"]] = (item["entidad"], source["titulo"])
    sources = "".join(f"<li><strong>{e(owner)}</strong> — {e(title)}<br><a href='{e(url)}'>{e(url)}</a></li>" for url, (owner, title) in sorted(unique.items(), key=lambda pair: (pair[1][0].lower(), pair[1][1].lower())))
    cov_list, cov_count = coverage_sources()
    chapters.append(f"""<section class='chapter' id='fuentes'><div class='chapter-title'><div class='eyebrow'>Trazabilidad</div><h1>Método, límites y fuentes</h1></div><h2>Método aplicado</h2><ol><li>Inventario de 32 departamentos + Bogotá D.C.; no se usó una lista incompleta de 31.</li><li>Descubrimiento de portales oficiales de gobernación y capital; verificación HTTP y renderizado JavaScript de páginas dinámicas.</li><li>Crawling de enlaces de navegación y sitemaps XML para localizar cultura, participación, planeación, bancos, regalías y convocatorias.</li><li>Consulta SECOP II p6dx-8zbt en nombre y descripción; 12.850 candidatos de 2026; depuración a {len(SECOP)}.</li><li>Clasificación de instrumentos, requisitos, presencia y acción; generación única para PDF, sitio, cobertura y CSV.</li><li>Validación de integridad, enlaces, paginación, filtros y páginas A4.</li></ol><h2>Qué significa “exhaustiva”</h2><p><strong>Exhaustividad operativa verificable:</strong> todas las unidades territoriales del censo fueron incluidas; todas las capas exigidas tienen una entrada en el registro; y cada ausencia o bloqueo se declara. No significa que internet sea estático ni que una entidad no pueda publicar una convocatoria después del corte.</p><div class='callout warn'><strong>Brechas al cierre:</strong> {complete}/33 territorios tienen las seis capas resueltas. Cesar y Magdalena requieren revisión manual. Los ayuntamientos y entidades locales por fuera de la capital no se enumeran uno a uno: sus procesos abiertos se cubren mediante SECOP II y las rutas departamentales/nacionales.</div><h2>Limitaciones</h2><ul><li>Fotografía al {DATA['corte']}; convocatorias y plazos cambian por adenda.</li><li>SECOP no expone la hora de cierre en el dataset. 952 candidatos equivalen a “revisar”, no a “postular sin verificar”.</li><li>601 intersecciones no prueban por sí solas que el objeto sea de economía plateada.</li><li>Los portales con anti-bot o menús dinámicos pueden ocultar secciones; se marcan como limitados.</li><li>Algunas páginas locales enlazadas son programas o noticias; no necesariamente una convocatoria abierta.</li><li>No es asesoría jurídica. La elegibilidad depende del postulante y del proyecto concreto.</li><li>Documentos escaneados, como el Anexo 15 SGR, se citan por vigencia y URL, sin inventar contenido no legible.</li></ul><h2>Archivos de control</h2><ul><li><a href='{SITE}oportunidades.csv'>Dataset general ({len(ITEMS)} registros)</a></li><li><a href='{SITE}secop_oportunidades.csv'>Universo SECOP ({len(SECOP)} registros)</a></li><li><a href='{SITE}cobertura_territorial.json'>Evidencia de cobertura (33 × 6)</a></li><li><a href='{SITE}cobertura.html'>Tablero de cobertura</a></li></ul><h2>Fuentes de las oportunidades</h2><ol class='small'>{sources}</ol><h2>Anexo · evidencia de cobertura territorial</h2><p class='small'>{cov_count} URLs únicas de evidencia territorial. Esta lista incluye las fuentes de las 33 matrices, no los 952 avisos SECOP que ya aparecen enlazados en su tabla.</p><ol class='small'>{cov_list}</ol><div class='signature'>Economía Plateada Colombia · versión 2.0 · {DATA['corte']}<br>Explorador: <a href='{SITE}'>{SITE}</a><br>Archivo PDF: {PDF}</div></section>""")
    document = """<!doctype html><html lang='es'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Informe exhaustivo · Economía Plateada Colombia</title><meta name='description' content='Universo auditado de fuentes, SECOP II, regalías, ministerios y financiación para economía plateada en Colombia.'><link rel='icon' href='favicon.svg' type='image/svg+xml'><link rel='stylesheet' href='informe.css'></head><body>""" + "".join(chapters) + "</body></html>"
    return document


if __name__ == "__main__":
    document = make_document()
    output = ROOT / "documento.html"
    output.write_text(document, encoding="utf-8")
    assert all(item["id"] in document for item in BASE)
    assert all(item["id_proceso"] in document for item in SECOP)
    print(json.dumps({"archivo": str(output), "caracteres": len(document), "registros": len(ITEMS), "secop": len(SECOP)}, ensure_ascii=False))
